import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
} from '../remotionShim';
import { Pie } from "@remotion/shapes";
// Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Schema ---



export type CorporateSlideProps = Record<string, any>;

// --- Helper Components ---

const ChartSegmentLabel: React.FC<{
  cx: number;
  cy: number;
  radius: number;
  startAngle: number; // radians
  endAngle: number;   // radians
  value: number;
  color: string;
  delay: number;
  textColor: string;
}> = ({ cx, cy, radius, startAngle, endAngle, value, color, delay, textColor }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Calculate position (polar to cartesian)
  // Midpoint angle
  const midAngle = startAngle + (endAngle - startAngle) / 2;
  
  // Position text at 70% of radius (inside the donut)
  const textRadius = radius * 0.75;
  const x = cx + textRadius * Math.cos(midAngle);
  const y = cy + textRadius * Math.sin(midAngle);

  // Animation
  const opacity = interpolate(
    frame - delay,
    [0, 15],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const scale = spring({
    frame: frame - delay,
    fps,
    config: { stiffness: 200, damping: 15 },
  });

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        transform: `translate(-50%, -50%) scale(${scale})`,
        opacity,
        color: textColor, 
        fontFamily: "Inter",
        fontWeight: 700,
        fontSize: radius * 0.15,
        pointerEvents: "none",
        textShadow: "0px 2px 4px rgba(0,0,0,0.2)",
      }}
    >
      {Math.round(value)}%
    </div>
  );
};

// --- Main Component ---

const CorporateSlide: React.FC<CorporateSlideProps> = ({
  backgroundColorLeft = "#FFFFFF",
  backgroundColorRight = "#0B2553",
  textColorLeft = "#000000",
  textColorRight = "#FFFFFF",
  pieSegmentTextColor = "#FFFFFF",
  title = "Empresas têm políticas de viagens definidas e documentadas",
  bodyText = "Outro fator relevante na gestão de viagens corporativas é a política de viagens da empresa. A grande maioria dos viajantes (90%) conhece e tem acesso a essas diretrizes.\n\nQuando questionados sobre a satisfação com a gestão de viagens, 71% dos viajantes afirmam estar satisfeitos com os processos atuais.\n\nContudo, há uma diferença de percepção entre gêneros.",
  chartTitle = "Avaliação de processos",
  chartValues = [71, 23, 6],
  chartLabels = ["Bom ou muito bom", "Nutro", "Ruim ou muito ruim"],
  chartColors = ["#00D895", "#007AFF", "#FFFFFF"],
  durationInSeconds = 10,
  animationSpeed = 1,
}) => {
  useFontLoader(["Inter", "Roboto"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Normalize Chart Data
  const totalValue = chartValues.reduce((a, b) => a + b, 0);
  const normalizedValues = chartValues.map((v) => (totalValue === 0 ? 0 : v / totalValue));
  
  // Calculate cumulative angles for rotation
  // Start at -PI/2 (12 o'clock)
  let cumulativeAngle = -Math.PI / 2;
  const segments = normalizedValues.map((val, i) => {
    const startAngle = cumulativeAngle;
    const endAngle = startAngle + val * Math.PI * 2;
    cumulativeAngle = endAngle;
    return {
      value: val, // 0-1
      originalValue: chartValues[i],
      startAngle,
      endAngle,
      color: chartColors[i] || "#ccc",
      label: chartLabels[i] || `Item ${i + 1}`,
    };
  });

  // Animations
  const leftEntrance = spring({
    frame,
    fps,
    config: { damping: 200 },
    durationInFrames: 30 / animationSpeed,
  });

  const rightEntrance = spring({
    frame: frame - 10,
    fps,
    config: { damping: 200 },
    durationInFrames: 30 / animationSpeed,
  });
  
  const textOpacity = interpolate(frame, [15, 45], [0, 1], { extrapolateRight: "clamp" });
  const textSlide = interpolate(frame, [15, 45], [20, 0], { extrapolateRight: "clamp", easing: (t) => t * (2 - t) });

  // Chart Animation
  const chartRadius = Math.min(width, height) * 0.18;
  const donutHoleRadius = chartRadius * 0.5;
  const chartDelay = 30;
  
  // Layout Constants
  const leftWidth = width * 0.5;
  
  return (
    <AbsoluteFill style={{ flexDirection: "row", fontFamily: "Inter" }}>
      
      {/* LEFT PANEL */}
      <div
        style={{
          width: leftWidth,
          height: "100%",
          backgroundColor: backgroundColorLeft,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          padding: `0 ${width * 0.06}px`,
          transform: `translateX(${(1 - leftEntrance) * -100}px)`,
          position: "relative",
          zIndex: 1,
        }}
      >
        <h1
          style={{
            fontSize: width * 0.035,
            fontWeight: 700,
            lineHeight: 1.1,
            color: textColorLeft,
            marginBottom: height * 0.05,
            opacity: textOpacity,
            transform: `translateY(${textSlide}px)`,
          }}
        >
          {title}
        </h1>
        
        {bodyText.split("\n\n").map((para, i) => (
          <p
            key={i}
            style={{
              fontSize: width * 0.014,
              lineHeight: 1.5,
              color: textColorLeft,
              marginBottom: height * 0.02,
              opacity: interpolate(frame, [25 + i * 10, 55 + i * 10], [0, 0.8], { extrapolateRight: "clamp" }),
              transform: `translateY(${interpolate(frame, [25 + i * 10, 55 + i * 10], [20, 0], { extrapolateRight: "clamp" })}px)`,
              whiteSpace: "pre-wrap",
            }}
          >
            {para}
          </p>
        ))}
      </div>

      {/* RIGHT PANEL */}
      <div
        style={{
          flex: 1,
          height: "100%",
          backgroundColor: backgroundColorRight,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transform: `translateX(${(1 - rightEntrance) * 100}px)`,
          position: "relative",
          zIndex: 2,
        }}
      >
        <h2
          style={{
            fontSize: width * 0.02,
            fontWeight: 400,
            color: textColorRight,
            marginBottom: height * 0.05,
            opacity: interpolate(frame, [chartDelay, chartDelay + 20], [0, 1], { extrapolateRight: "clamp" }),
          }}
        >
          {chartTitle}
        </h2>

        {/* CHART CONTAINER */}
        <div style={{ position: "relative", width: chartRadius * 2, height: chartRadius * 2 }}>
          <svg
            width={chartRadius * 2}
            height={chartRadius * 2}
            viewBox={`0 0 ${chartRadius * 2} ${chartRadius * 2}`}
            style={{ overflow: "visible" }}
          >
            <g transform={`translate(${chartRadius}, ${chartRadius})`}>
              {segments.map((seg, i) => {
                // SVG wrapper logic placeholder, actual Pie is below
                return null; 
              })}
            </g>
          </svg>

          {/* Rendering Pies as Absolute positioned layers */}
          {segments.map((seg, i) => {
            const segmentDelay = chartDelay + i * 10;
            // Animate the "reveal" of the slice
            // We want it to wipe from 0 to its full length.
            const animatedProgress = spring({
              frame: frame - segmentDelay,
              fps,
              config: { stiffness: 50, damping: 10 },
            }) * seg.value;

            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  width: "100%",
                  height: "100%",
                  // Fix rotation to align Pie's natural 12 o'clock start with trig-based layout
                  transform: `rotate(${seg.startAngle + Math.PI / 2}rad)`,
                }}
              >
                <Pie
                  radius={chartRadius}
                  progress={animatedProgress}
                  rotation={0} // Relative to the div rotation
                  fill={seg.color}
                  stroke="none"
                />
              </div>
            );
          })}
          
          {/* Donut Hole */}
          <div
            style={{
              position: "absolute",
              top: "50%",
              left: "50%",
              width: donutHoleRadius * 2,
              height: donutHoleRadius * 2,
              backgroundColor: backgroundColorRight,
              borderRadius: "50%",
              transform: "translate(-50%, -50%)",
              boxShadow: "0 0 20px rgba(0,0,0,0.1)", // Subtle depth
            }}
          />

          {/* Labels on Chart */}
          {segments.map((seg, i) => (
             <ChartSegmentLabel
               key={`label-${i}`}
               cx={chartRadius}
               cy={chartRadius}
               radius={chartRadius}
               startAngle={seg.startAngle}
               endAngle={seg.endAngle}
               value={seg.originalValue}
               color={seg.color}
               delay={chartDelay + 20 + i * 5}
               textColor={pieSegmentTextColor}
             />
          ))}

        </div>

        {/* LEGEND */}
        <div
          style={{
            marginTop: height * 0.08,
            display: "flex",
            flexDirection: "row",
            gap: width * 0.02,
            flexWrap: "wrap",
            justifyContent: "center",
            width: "80%",
          }}
        >
          {segments.map((seg, i) => {
             const legendDelay = chartDelay + 30 + i * 5;
             const legendOpacity = interpolate(frame, [legendDelay, legendDelay + 10], [0, 1], { extrapolateRight: "clamp" });
             
             return (
               <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 10,
                  opacity: legendOpacity,
                }}
               >
                 <div
                   style={{
                     width: 16,
                     height: 16,
                     backgroundColor: seg.color,
                     borderRadius: 2,
                   }}
                 />
                 <span
                   style={{
                     color: textColorRight,
                     fontSize: width * 0.012,
                     fontWeight: 500,
                   }}
                 >
                   {seg.label}
                 </span>
               </div>
             );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CorporateSlide;